SourceCode.Declaration:
/// <summary>
/// What HSMobileOpsLicenseSvc/getLicense returns. The app verifies LicenseKey itself, against
/// the customer public key inside its own already-activated certificate - ServerUtcNow exists
/// so the app's own expiry/clock-rollback checks are anchored to this server's clock, not the
/// device's own (which a worker could wind backward) - see LicenseRepository's own doc.
/// </summary>
[DataContractAttribute]
class HSMobileOpsGetLicenseResponse
{
    boolean success;
    str     errorCode;
    str     message;
    str     licenseKey;
    str     serverUtcNow;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

/// <summary>
/// NO_LICENSE, LICENSE_INVALID, LICENSE_EXPIRED - same codes HSMobileOpsLicense::verify()
/// already returns everywhere else, so the app's own error handling for this call is nothing
/// new relative to the sign-in path.
/// </summary>
[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

/// <summary>
/// The raw WMSLIC1... string exactly as imported - the app verifies its signature itself
/// against its own stored certificate's customer public key, never trusting this response's
/// Success flag alone.
/// </summary>
[DataMemberAttribute('LicenseKey')]
public str parmLicenseKey(str _value = licenseKey)
{
    licenseKey = _value;
    return licenseKey;
}

/// <summary>
/// This server's own UTC clock at the moment of the call, ISO 8601 - what the app's clock-
/// rollback check compares against, instead of trusting the device's own clock alone.
/// </summary>
[DataMemberAttribute('ServerUtcNow')]
public str parmServerUtcNow(str _value = serverUtcNow)
{
    serverUtcNow = _value;
    return serverUtcNow;
}
